import {
  Column,
  CreateDateColumn,
  Entity,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { Customer } from '../../customers/entities/customer.entity';

/**
 * A product image that was uploaded through the admin area. The file name on
 * disk is generated by the server, so an uploaded file can never overwrite
 * another file or escape the upload directory.
 */
@Entity('product_images')
export class ProductImage {
  @PrimaryGeneratedColumn()
  id!: number;

  /** Name the admin uploaded. Display only; never used as a path. */
  @Column({ name: 'original_name', length: 255 })
  originalName!: string;

  /** Server generated file name, unique across uploads. */
  @Column({ name: 'stored_name', unique: true, length: 100 })
  storedName!: string;

  @Column({ name: 'mime_type', length: 80 })
  mimeType!: string;

  @Column({ name: 'size_bytes', type: 'integer' })
  sizeBytes!: number;

  @Column({
    name: 'created_by_customer_id',
    type: 'integer',
    nullable: true,
  })
  createdByCustomerId!: number | null;

  @ManyToOne(() => Customer, { nullable: true, onDelete: 'SET NULL' })
  @JoinColumn({ name: 'created_by_customer_id' })
  createdBy!: Customer | null;

  @CreateDateColumn({ name: 'created_at' })
  createdAt!: Date;
}
